/* Complete academic demo. Personal data and money remain in memory only. */
(() => {
  'use strict';
  const D = window.UniCaronaDomain;
  const esc = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const attr = (data) => esc(JSON.stringify(data));
  const cash = D.money;
  const dateLabel = v => v ? new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${v.slice(0,10)}T12:00:00`)) : '—';
  const dayNames = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
  const shifts = {morning:'Manhã',afternoon:'Tarde',night:'Noite','full-time':'O dia todo',variable:'Horários variados'};
  const statuses = {planned:'Programado',active:'Ativo',confirmed:'Confirmada',pending:'Aguardando',accepted:'Aceito · falta pagamento',approved:'Aprovado',rejected:'Rejeitado',failed:'Não aprovado',cancelled:'Cancelado',expired:'Vencido',boarded:'Embarque registrado',awaiting_confirmation:'Confirmação final pendente',completed:'Concluído',under_review:'Em análise',blocked:'Bloqueado',released:'Liberado',credited:'Crédito integral',retained:'Destinado ao app',future:'Futuro',awaiting:'Aguardando confirmação',cancelled_renewal:'Renovação desativada',grace:'Carência · falta pagamento',renew_conflict:'Agenda sem vaga completa',interrupted:'Interrompido por segurança',ended:'Encerrado',renewed:'Renovado',no_class:'Sem aula',not_requested:'Não solicitado',financial_pending:'Dinheiro ainda em análise',resolved:'Análise concluída',waiting:'Na lista de interesse',replaced:'Substituído'};
  const badge = status => `<span class="m-badge ${['approved','confirmed','released','completed','active'].includes(status)?'good':['cancelled','expired','rejected','failed','blocked','interrupted'].includes(status)?'bad':'warn'}">${esc(statuses[status] || status)}</span>`;
  const goButton = (label,route,ref='',style='') => `<button type="button" class="m-button ${style}" data-m-go="${esc(route)}" data-ref="${esc(ref)}">${esc(label)}</button>`;
  const actionButton = (label,op,data={},style='',confirm='') => `<button type="button" class="m-button ${style}" data-m-action="${esc(op)}" data-input="${attr(data)}" ${confirm?`data-confirm="${esc(confirm)}"`:''}>${esc(label)}</button>`;
  const field = (name,label,value='',type='text',extra='',help='') => `<label class="m-field"><span>${esc(label)}</span><input name="${esc(name)}" aria-label="${esc(label)}" type="${type}" value="${esc(value)}" placeholder="${esc(type==='text'?label:'')}" ${extra}>${help?`<small class="m-help">${esc(help)}</small>`:''}</label>`;
  const select = (name,label,options,value='') => `<label class="m-field"><span>${esc(label)}</span><select name="${esc(name)}" aria-label="${esc(label)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
  const check = (name,label,checked=false,value='on') => `<label class="m-check"><input type="checkbox" name="${name}" value="${esc(value)}" ${checked?'checked':''}>${esc(label)}</label>`;
  const textarea = (name,label,value='') => `<label class="m-field"><span>${esc(label)}</span><textarea name="${name}" aria-label="${esc(label)}" placeholder="${esc(label)}" required maxlength="1200">${esc(value)}</textarea></label>`;
  const form = (op,fields,label='Salvar',data={}) => `<form data-m-form="${op}" data-input="${attr(data)}" novalidate>${fields}<p class="m-error" role="alert"></p><button class="m-button" type="submit">${esc(label)}</button></form>`;
  const notice = text => `<div class="m-notice">${esc(text)}</div>`;
  const empty = (title,text,route='buscar',label='Buscar caronas') => `<div class="m-empty"><h2>${esc(title)}</h2><p class="m-muted">${esc(text)}</p>${goButton(label,route)}</div>`;
  const summary = rows => `<dl class="m-summary">${rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`;
  const days = (chosen=[1,2,3,4,5],enabled=[0,1,2,3,4,5,6]) => `<fieldset><legend>Dias da semana</legend><div class="m-days">${enabled.map(i=>`<label>${check('weekdays',dayNames[i],chosen.includes(i),i)}</label>`).join('')}</div></fieldset>`;
  const academic = p => [p.course,p.periodStatus==='numbered'?`${p.periodNumber}º período`:p.periodStatus==='irregular'?'Matérias de períodos diferentes':'Sem período definido',p.classLabel?`Turma ${p.classLabel}`:'Turma não informada'].filter(Boolean).join(' · ');
  const avatar = p => p.photo && /^data:image\/(png|jpeg|webp);base64,/.test(p.photo) ? `<img class="m-avatar" src="${esc(p.photo)}" alt="Foto de ${esc(p.name)}">` : `<span class="m-avatar" aria-hidden="true">${esc(p.name.split(/\s+/).slice(0,2).map(v=>v[0]).join(''))}</span>`;
  const person = p => `<div class="m-person">${avatar(p)}<div><h3>${esc(p.name)}</h3><p class="m-help">${esc(academic(p))}</p></div></div>`;
  const steps = index => `<div class="m-steps" aria-label="Etapas da reserva">${['Escolha','Aceite','Pagamento','Viagem'].map((l,i)=>`<span class="${i<=index?'active':''}">${i+1}. ${l}</span>`).join('')}</div>`;
  const titles = {results:'Caronas para seu trajeto',ride:'Detalhes da carona',monthly:'Mensal da sua turma',request:'Sua solicitação',checkout:'Pagamento',reservation:'Sua carona',contract:'Seu plano mensal',minhas:'Minhas caronas',driver:'Ofereça uma carona',offer:'Publicar carona',edit:'Editar oferta',passengers:'Gerenciar trecho',wallet:'Carteira',perfil:'Seu perfil',settings:'Configurações',safety:'Segurança e ocorrências',report:'Relatar uma ocorrência',notifications:'Notificações',admin:'Administração',help:'Como podemos ajudar?',demo:'Apresentação do MVP',history:'Histórico'};
  function attach({root,profile,home}) {
    let state=D.createState(profile),route='inicio',ref='',query={type:'avulsa',region:profile.region||'Lago Azul',date:D.localDate(),direction:'ida'},filter='reservations',preview=null,photo='',timer,toastTimer;
    const app=document.createElement('section'); app.className='m-app'; app.hidden=true; root.querySelector('.d-footer').before(app);
    const toolbar=document.createElement('div'); toolbar.className='m-demo-bar'; toolbar.innerHTML=`<span>UNICEPLAC · demonstração acadêmica</span>${goButton('Apresentação','demo','','quiet')}`; root.querySelector('.d-content').prepend(toolbar);
    const dialog=document.createElement('dialog'); dialog.className='m-dialog'; root.append(dialog);
    const toast=document.createElement('div'); toast.className='m-toast'; toast.hidden=true; toast.setAttribute('role','status'); root.append(toast);
    const get=(list,id)=>state[list].find(x=>x.id===id); const me=()=>D.user(state); const rideFor=r=>get('rides',r.rideId); const parcelFor=r=>state.parcels.find(x=>x.reservationId===r.id);
    function notify(text){toast.textContent=text;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,3800);}
    function updateHome(){
      const p=me(); root.classList.toggle('d-has-name',p.name!=='Estudante');const dateInput=root.querySelector('#dashboard-date');dateInput.min=D.nowDate(state);if(dateInput.value<D.nowDate(state))dateInput.value=D.nowDate(state); root.querySelector('[data-greeting]').textContent=p.name==='Estudante'?'Olá, estudante.':`Olá, ${p.name.split(' ')[0]}.`; root.querySelector('[data-profile-course]').textContent=p.course||'Complete seu perfil acadêmico'; root.querySelector('[data-profile-placement]').textContent=p.course?[p.periodStatus==='numbered'?`${p.periodNumber}º período`:p.periodStatus==='irregular'?'Matérias de períodos diferentes':'Sem período definido',shifts[p.shift],p.classLabel?`Turma ${p.classLabel}`:'Turma não informada'].filter(Boolean).join(' · '):'Curso, período e turma ajudam a encontrar seu mensal.';
      root.querySelector('[data-profile-initials]').textContent=p.name.split(' ').slice(0,2).map(x=>x[0]).join('');
      const next=state.reservations.filter(x=>x.passengerId===p.id&&['confirmed','boarded','awaiting_confirmation'].includes(x.status)).sort((a,b)=>`${rideFor(a).date}${rideFor(a).time}`.localeCompare(`${rideFor(b).date}${rideFor(b).time}`))[0];
      const card=root.querySelector('.d-next-trip .d-empty-compact'); card.innerHTML=next?`<h3>${esc(rideFor(next).time)} · ${esc(dateLabel(rideFor(next).date))}</h3><p>${esc(rideFor(next).origin)} → ${esc(rideFor(next).destination)}</p>${goButton('Ver reserva','reservation',next.id,'secondary')}`:`<h3>Nenhuma carona marcada</h3><p>Busque seu trajeto e confirme uma reserva para acompanhar aqui.</p>`;
      root.querySelector('.d-caption').textContent='Ofertas e pagamentos fictícios para apresentar o MVP.';
      root.querySelector('.d-welcome p').innerHTML='<strong>Seu perfil está pronto para começar.</strong><br>Busque uma carona ou compartilhe seu trajeto.';
      toolbar.querySelector('span').textContent=`UNICEPLAC · ${p.role==='admin'?'Administração de exemplo':p.name} · demonstração`;
    }
    function navigate(next,id='',history=true){
      clearTimeout(timer);route=next;ref=id;preview=null;
      if (history){const url=new URL(location.href); if(['inicio','buscar'].includes(next)){url.searchParams.delete('tela');url.searchParams.delete('id');}else{url.searchParams.set('tela',next);id?url.searchParams.set('id',id):url.searchParams.delete('id');}window.history.pushState({uc:true},'',url);}
      render(); window.scrollTo({top:0,behavior:'instant'}); (app.hidden?(next==='buscar'?root.querySelector(root.querySelector('#dashboard-origin').readOnly?'#dashboard-destination':'#dashboard-origin'):root.querySelector('#dashboard-title')):app.querySelector('h1'))?.focus({preventScroll:true});
    }
    function render(){
      updateHome(); const isHome=['inicio','buscar'].includes(route);
      root.querySelectorAll('[data-view]').forEach(v=>v.hidden=true);root.querySelector('.d-page-heading').hidden=!isHome;app.hidden=isHome;
      root.classList.toggle('d-searching',isHome);
      if(isHome){home(route,false);root.querySelector('.d-page-heading').hidden=false;return;}
      root.querySelectorAll('.d-nav-item').forEach(b=>{const active=(route==='driver'||route==='offer'||route==='passengers'||route==='edit')?'oferecer':(['request','checkout','reservation','contract','history'].includes(route)?'minhas':route);b.dataset.page===active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current');});
      document.title=`${titles[route]||'Painel'} | UniCarona`;
      const header=`<button class="m-link" type="button" data-m-back>← Voltar</button><p class="m-kicker">UniCarona · UNICEPLAC</p><h1 tabindex="-1">${esc(titles[route]||'Painel')}</h1>`;
      try {app.innerHTML=header+view()+`<div class="m-toolbar">${goButton('Carteira','wallet','','quiet')}${goButton('Segurança','safety','','quiet')}${goButton('Ajuda','help','','quiet')}${goButton('Configurações','settings','','quiet')}</div>`;const period=app.querySelector('[name=periodNumber]');if(period){period.disabled=me().periodStatus&&me().periodStatus!=='numbered';period.required=!period.disabled;}}
      catch(error){app.innerHTML=header+notice(error.message)+goButton('Voltar ao início','inicio');}
    }
    function rideRow(ride,driverView=false){const p=D.user(state,ride.driverId);return `<article class="m-row"><div><h3>${esc(ride.time)} · ${esc(dateLabel(ride.date))}</h3><p>${esc(ride.origin)} → ${esc(ride.destination)}</p><p class="m-help">${esc(driverView?statuses[ride.status]:p.name)} · ${D.available(state,ride.id)} de ${ride.capacity} vagas · ${cash(ride.priceCents)}</p></div>${goButton(driverView?'Gerenciar':'Ver carona',driverView?'passengers':'ride',ride.id,'secondary')}</article>`;}
    function reservationRow(r){const ride=rideFor(r);return `<article class="m-row"><div><h3>${esc(ride.time)} · ${esc(dateLabel(ride.date))}</h3><p>${esc(ride.origin)} → ${esc(ride.destination)}</p><p>${badge(r.status)} ${r.contractId?'<span class="m-badge">Mensal</span>':''}</p></div>${goButton('Ver reserva','reservation',r.id,'secondary')}</article>`;}
    function results(){
      const entries=D.search(state,query);
      return `<p class="m-route">${esc(query.region)} ${query.direction==='volta'?'←':'→'} UNICEPLAC</p><p class="m-muted">${query.type==='mensal'?'Rotinas mensais':dateLabel(query.date)} · ofertas fictícias</p>${query.type==='mensal'?form('filters',check('compatibleOnly','Somente da minha turma',query.compatibleOnly),'Aplicar filtro'): `<details class="m-filter-panel m-section"><summary>Filtrar resultados</summary>${form('filters',`<div class="m-two">${field('time','A partir de (opcional)',query.time||'','time')}${field('maxPrice','Preço máximo em R$ (opcional)',query.maxPrice?query.maxPrice/100:'','number','min="0.01" step="0.01"')}</div>${check('automatic','Somente aceite automático',query.automatic)}${check('onlyAvailable','Somente com vaga disponível',query.onlyAvailable)}`,'Aplicar filtros')}</details>`}
      ${entries.length?`<div class="m-list">${entries.map(entry=>query.type==='mensal'?`<article class="m-row"><div><h3>${esc(D.user(state,entry.driverId).name)}</h3><p>${esc(entry.region)} ↔ UNICEPLAC</p><p class="m-help">${esc(entry.weekdays.map(d=>dayNames[d]).join(', '))} · ${entry.compatible?'Mesma turma':'Confira a compatibilidade acadêmica'}</p></div>${goButton('Ver mensal','monthly',entry.id,'secondary')}</article>`:rideRow(entry)).join('')}</div>`:empty('Nenhuma carona para esses filtros','Ajuste a região, o horário ou a data para buscar novamente.')} ${goButton('Ajustar trajeto','buscar','','quiet')}`;
    }
    function rideDetail(){const ride=get('rides',ref);if(!ride)throw Error('Oferta não encontrada. Faça uma nova busca.');const driver=D.user(state,ride.driverId);
      return `${steps(0)}<div class="m-grid"><div>${person(driver)}<p class="m-route">${esc(ride.origin)} → ${esc(ride.destination)}</p>${summary([['Quando',`${dateLabel(ride.date)} · ${ride.time}`],['Encontro',ride.meeting],['Veículo',`${ride.vehicle.model} · ${ride.vehicle.color}`],['Placa',ride.vehicle.plate],['Vagas',`${D.available(state,ride.id)} disponíveis de ${ride.capacity}`],['Aceite',ride.automatic?'Automático após revalidar a vaga':'O motorista precisa aceitar']])}<p class="m-help">Perfil autodeclarado. Aprovação fictícia de motorista e veículo.</p><p>${esc(ride.notes)}</p><div class="m-actions">${goButton('Relatar ocorrência','report',driver.id,'quiet')}${actionButton('Bloquear novas combinações','block',{other:driver.id},'quiet','Bloquear impede novos encontros com essa pessoa. Vínculos mensais futuros ficam interrompidos para análise.')}</div></div><aside class="m-panel"><h2>Uma vaga para você</h2><p class="m-price">${cash(ride.priceCents)}</p><p class="m-help">Preço por passageiro e por trecho. Não é uma cotação real de percurso.</p>${D.available(state,ride.id)>0&&ride.status==='planned'?actionButton('Solicitar vaga','requestRide',{rideId:ride.id}):notice('Este trecho está sem vaga ou já foi encerrado.')}<p class="m-help">A reserva é confirmada após aceite e pagamento fictício. Um pedido pendente não ocupa vaga.</p></aside></div>`;}
    function monthly(){const routine=get('routines',ref);if(!routine)throw Error('Rotina não encontrada.');const driver=D.user(state,routine.driverId),compatible=D.sameClass(me(),driver);
      return `${person(driver)}<p class="m-route">${esc(routine.region)} ↔ UNICEPLAC</p>${summary([['Curso e turma',academic(driver)],['Horários',Object.entries(routine.times).map(([d,t])=>`${d==='ida'?'Ida':'Volta'} ${t}`).join(' · ')],['Encontro',routine.meeting],['Vagas por trecho',routine.capacity]])}${!compatible?notice('O mensal exige mesmo curso, número do período e turma. Seu perfil ainda não combina com essa rotina.')+goButton('Conferir meu perfil','perfil'):`<div class="m-grid m-section"><div>${form('previewMonthly',field('startDate','Início do plano',D.nowDate(state),'date',`min="${D.nowDate(state)}" required`)+select('directions','Sentidos contratados',[...Object.keys(routine.times).map(d=>[d,d==='ida'?'Só ida':'Só volta']),...(routine.times.ida&&routine.times.volta?[['ambos','Ida e volta']]:[])],routine.times.ida&&routine.times.volta?'ambos':Object.keys(routine.times)[0])+days(routine.weekdays,routine.weekdays),'Conferir agenda e valor',{routineId:routine.id})}</div><aside class="m-panel"><h2>Mesma turma, mesma rotina</h2><p>10% de desconto sobre os trechos da agenda escolhida.</p><p class="m-help">Feriados e recessos conhecidos saem do cálculo. A entrada no mês considera apenas os dias futuros. Todas as vagas precisam estar disponíveis.</p>${actionButton('Entrar na lista de interesse','waitlist',{routineId:routine.id},'quiet')}</aside></div><div data-monthly-preview></div>`}`;
    }
    function previewMarkup(p){return `<section class="m-panel m-section"><h2>Sua agenda</h2>${summary([['Período',`${dateLabel(p.startDate)} a ${dateLabel(p.endDate)}`],['Trechos',p.lines.length],['Total sem desconto',cash(p.originalCents)],['Desconto',`${Math.round(p.discount*100)}%`],['Total do mensal',cash(p.totalCents)]])}${p.excludedDates.length?notice(`Datas conhecidas excluídas: ${p.excludedDates.map(x=>`${dateLabel(x.date)} — ${x.title}`).join('; ')}`):''}<details class="m-section"><summary>Ver todos os trechos e parcelas</summary><div class="m-scroll">${p.lines.map(l=>`<div class="m-row"><span>${esc(dateLabel(l.date))} · ${l.direction==='ida'?'Ida':'Volta'} ${esc(l.time)}</span><strong>${cash(l.cents)}</strong></div>`).join('')}</div></details>${p.conflicts.length?notice(`${p.conflicts.length} trecho(s) sem disponibilidade. Não vendemos um plano parcial.`):actionButton('Solicitar mensal ao motorista','requestMonthly',{routineId:p.routineId,startDate:p.startDate,weekdays:p.weekdays,directions:p.directions})}<p class="m-help">O motorista precisa aceitar esse plano específico. O pagamento congela a agenda e o preço. Cancelar a renovação mantém os direitos do período pago.</p></section>`;}
    function requestView(){const request=get('requests',ref);if(!request||request.passengerId!==me().id)throw Error('Solicitação não disponível neste perfil.');const payment=state.payments.find(x=>x.requestId===request.id);
      return `${steps(request.status==='pending'?1:2)}${badge(request.status)}<div class="m-section">${person(D.user(state,request.driverId))}</div>${summary([['Modalidade',request.type==='mensal'?'Mensal':'Avulsa'],['Trechos',request.lines.length],['Valor',cash(request.totalCents)],['Situação',statuses[request.status]]])}${request.status==='pending'?notice('O motorista ainda precisa aceitar. Seu pedido não ocupa vaga. Use Apresentação para percorrer a etapa do motorista.'):''}${request.reason?notice(request.reason):''}<div class="m-actions">${payment&&['pending','failed'].includes(payment.status)&&request.status==='accepted'?goButton('Ir para pagamento','checkout',payment.id):''}${request.status==='confirmed'?goButton('Ver minhas caronas','minhas'):''}${goButton('Acompanhar pedidos','minhas','','secondary')}${goButton('Apresentação','demo','','quiet')}</div>`;
    }
    function checkout(){const payment=get('payments',ref);if(!payment||payment.passengerId!==me().id)throw Error('Pagamento não disponível neste perfil.');const request=get('requests',payment.requestId);
      if(payment.status==='approved')return `${steps(3)}${badge('approved')}<h2 class="m-section">Pagamento fictício confirmado</h2>${summary([['Valor',cash(payment.amountCents)],['Crédito utilizado',cash(payment.creditCents)],['Entrada fictícia',cash(payment.externalCents)],['Método',payment.method==='pix'?'Pix de demonstração':'Cartão de demonstração'],['Comprovante',payment.id]])}<div class="m-actions">${goButton('Acompanhar minha carona',request.type==='mensal'?'contract':'reservation',request.type==='mensal'?state.contracts.find(x=>x.requestId===request.id).id:state.reservations.find(x=>x.requestId===request.id).id)}</div>`;
      if(payment.status==='expired'||request.status!=='accepted')return notice('Pagamento vencido ou pedido encerrado. Nenhum valor foi recebido.')+goButton('Buscar novamente','buscar');
      return `${steps(2)}<div class="m-grid"><div>${notice('Nenhum dinheiro real será movimentado. Use os meios fictícios abaixo; não informe cartão nem chave bancária real.')}${payment.status==='failed'?notice('O pagamento de exemplo não foi aprovado. Revise o cenário ou tente novamente.'):''}${form('pay',select('method','Forma de pagamento',[['pix','Pix de demonstração'],['card','Cartão de demonstração']],'pix')+`<div class="m-panel m-section"><h3 data-payment-title>Pix de exemplo</h3><p class="m-help">Identificador demonstrativo: ${esc(payment.id)}. Este código não pode ser pago em um banco.</p></div>`+check('useCredit',`Usar crédito disponível (${cash(D.wallet(state).credit)})`,D.wallet(state).credit>0),'Simular pagamento',{paymentId:payment.id})}</div><aside class="m-panel"><h2>Resumo</h2>${summary([['Modalidade',request.type==='mensal'?'Mensal':'Avulsa'],['Trechos',request.lines.length],['Total',cash(payment.amountCents)]])}<p class="m-help">Revalidamos todas as vagas ao aprovar. Valores futuros não ficam disponíveis para saque.</p>${badge(payment.status)}</aside></div>`;
    }
    function reservation(){const r=get('reservations',ref);if(!r||r.passengerId!==me().id)throw Error('Reserva não disponível neste perfil.');const ride=rideFor(r),parcel=parcelFor(r),driver=D.user(state,r.driverId);
      return `${badge(r.status)}<div class="m-grid m-section m-reservation-grid"><div>${person(driver)}<p class="m-route">${esc(ride.origin)} → ${esc(ride.destination)}</p>${summary([['Quando',`${dateLabel(ride.date)} · ${ride.time}`],['Encontro',ride.meeting],['Veículo',`${ride.vehicle.model} · ${ride.vehicle.color}`],['Placa',ride.vehicle.plate],['Parcela paga',cash(r.priceCents)],['Situação financeira',statuses[parcel.status]],['Embarque',r.boardedAt?'Registrado com PIN':'Ainda não registrado'],['Disponibilidade',r.availability==='fulfilled_absence'?'Motorista declarou disponibilidade; passageiro ausente':r.availability==='no_class'?'Sem aula posterior à contratação':r.availability==='fulfilled'?'Conclusão declarada':'Aguardando']])}${r.proposedTime&&r.timeResponse==='pending'?notice(`Novo horário proposto: ${r.proposedTime}. O trecho continua com o horário anterior até o acordo.`)+`<div class="m-actions">${actionButton('Concordo com o horário','replyTime',{reservationId:r.id,accept:true})}${actionButton('Não posso nesse horário','replyTime',{reservationId:r.id,accept:false},'quiet')}</div>`:''}<div class="m-actions">${goButton('Relatar ocorrência','report',`${driver.id}|${r.id}`,'quiet')}${actionButton('Compartilhar detalhes','share',{reservationId:r.id},'quiet')}${actionButton('Contato de demonstração','contact',{reservationId:r.id},'quiet')}</div></div><aside class="m-panel"><h2>${r.status==='confirmed'?'Seu código de embarque':'Acompanhe seu trecho'}</h2>${r.status==='confirmed'?`<span class="m-pin">${esc(r.pin)}</span><p class="m-help">Confira placa e veículo antes de informar o código ao motorista. Cada passageiro tem um PIN para cada trecho.</p>`:''}${r.status==='boarded'?notice('Embarque registrado. O PIN não finaliza a viagem e não libera o pagamento.'):''}${r.status==='awaiting_confirmation'?`<p>O motorista declarou ${r.availability==='no_class'?'Sem aula':r.availability==='fulfilled_absence'?'disponibilidade cumprida, com sua ausência':'a conclusão'}. Confira esse registro.</p><p class="m-help">Janela proposta de 24h: até ${esc(new Date(r.deadline).toLocaleString('pt-BR'))}. Uma contestação impede a liberação automática desta parcela.</p>${actionButton('Confirmar registro final','confirmFinal',{reservationId:r.id})}`:''}<div class="m-actions">${goButton('Contestar ou pedir análise','report',`${driver.id}|${r.id}|dispute`,'quiet')}${r.status==='confirmed'&&!r.contractId?goButton('Cancelar minha reserva','report',`${driver.id}|${r.id}|cancel`,'quiet'):''}</div>${r.contractId&&r.status==='confirmed'?goButton('Avisar ausência','report',`${driver.id}|${r.id}|absence`,'quiet'):''}${r.contractId?goButton('Gerenciar mensal','contract',r.contractId,'secondary'):''}</aside></div>`;
    }
    function contract(){const c=get('contracts',ref);if(!c||![c.passengerId,c.driverId].includes(me().id))throw Error('Plano não disponível neste perfil.');const driver=D.user(state,c.driverId),rows=state.reservations.filter(x=>x.contractId===c.id);
      return `${badge(c.status)}<div class="m-section">${person(driver)}</div>${summary([['Período pago',`${dateLabel(c.startDate)} a ${dateLabel(c.endDate)}`],['Dias',c.weekdays.map(x=>dayNames[x]).join(', ')],['Sentidos',c.directions==='ambos'?'Ida e volta':c.directions==='ida'?'Só ida':'Só volta'],['Total pago',cash(c.totalCents)],['Renovação',c.renew?'Permitida após novo aceite e pagamento':'Desativada'],['Ausências registradas',c.absenceCount]])}${c.status==='grace'?notice('Carência demonstrativa de 72h. Vagas futuras retidas quando toda a agenda está livre. Não é permitido embarcar no novo período sem pagamento.'):''}${c.status==='renew_conflict'?notice('A nova agenda não está totalmente livre. Não há renovação parcial nem retirada de reservas existentes.'):''}<div class="m-actions">${me().id===c.passengerId&&c.renew? actionButton('Solicitar renovação','renewMonthly',{contractId:c.id}):''}${me().id===c.passengerId&&c.renew?actionButton('Desativar renovação','cancelMonthly',{contractId:c.id},'quiet','O período pago continuará disponível. Apenas a renovação será desativada.'):''}${me().id===c.driverId?goButton('Encerrar vínculo mensal','report',`${c.passengerId}|${c.id}|remove`,'quiet'):''}</div><h2 class="m-section">Agenda e parcelas</h2><div class="m-list">${rows.map(r=>me().id===r.passengerId?reservationRow(r):rideRow(rideFor(r),true)).join('')}</div>`;
    }
    function mine(){const p=me(); const tabs=[['reservations','Viagens'],['requests','Pedidos'],['contracts','Mensais'],['offers','Ofertas'],['history','Histórico']];let list;
      if(filter==='requests')list=state.requests.filter(x=>x.passengerId===p.id).slice().reverse().map(x=>`<article class="m-row"><div><h3>${x.type==='mensal'?'Mensal':'Avulsa'} · ${esc(D.user(state,x.driverId).name)}</h3><p>${badge(x.status)} · ${cash(x.totalCents)}</p></div>${goButton('Ver pedido','request',x.id,'secondary')}</article>`);
      else if(filter==='contracts')list=state.contracts.filter(x=>[x.passengerId,x.driverId].includes(p.id)).map(x=>`<article class="m-row"><div><h3>${dateLabel(x.startDate)} a ${dateLabel(x.endDate)}</h3><p>${badge(x.status)} · ${cash(x.totalCents)}</p></div>${goButton('Ver plano','contract',x.id,'secondary')}</article>`);
      else if(filter==='offers')list=state.rides.filter(x=>x.driverId===p.id).map(x=>rideRow(x,true));
      else list=state.reservations.filter(x=>x.passengerId===p.id&&(filter==='history'?['cancelled','completed','under_review'].includes(x.status):!['cancelled','completed'].includes(x.status))).map(reservationRow);
      if(filter==='history')list=list.concat(state.rides.filter(x=>x.driverId===p.id&&(['completed','cancelled','no_class'].includes(x.status)||x.date<D.nowDate(state))).map(x=>rideRow(x,true)));
      return `<div class="m-tabs" role="group" aria-label="Filtrar minhas caronas">${tabs.map(([k,l])=>`<button type="button" class="m-button quiet" data-m-filter="${k}" aria-pressed="${k===filter}">${l}</button>`).join('')}</div>${list.length?`<div class="m-list">${list.join('')}</div>`:empty('Nada por aqui ainda','Seus pedidos, reservas e ofertas aparecerão aqui conforme você percorrer o MVP.')}<h2 class="m-section">Seus interesses em mensais</h2>${state.waitlist.filter(x=>x.userId===p.id&&x.status==='waiting').map(x=>`<div class="m-row"><div><h3>${esc(get('routines',x.routineId).region)}</h3><p class="m-help">Sem reserva nem garantia de vaga.</p></div>${actionButton('Retirar interesse','leaveWaitlist',{waitlistId:x.id},'quiet')}</div>`).join('')||'<p class="m-muted">Nenhum interesse registrado.</p>'}<div class="m-actions">${goButton('Oferecer uma carona','driver','','quiet')}${goButton('Notificações','notifications','','quiet')}</div>`;
    }
    function driver(){const p=me();if(p.role==='admin')return notice('Troque para o perfil de um aluno em Apresentação para oferecer caronas.'); const application=state.applications.filter(x=>x.userId===p.id).at(-1);const own=state.rides.filter(x=>x.driverId===p.id&&!['cancelled','completed','no_class'].includes(x.status));
      return `${badge(p.driverStatus)}${application?notice(application.status==='pending'?'Motorista e veículo em análise fictícia. A publicação será liberada após aprovação.':application.decision):''}${p.driverStatus==='approved'?`<div class="m-grid m-section"><div><h2>Seu caminho pode levar mais alguém</h2><p class="m-muted">Publique um trecho avulso ou uma rotina mensal para sua turma.</p>${summary([['Veículo',`${p.vehicle.model} · ${p.vehicle.color}`],['Placa',p.vehicle.plate],['Vagas de passageiros',p.vehicle.capacity]])}<div class="m-actions">${goButton('Publicar carona','offer')}${goButton('Recebimentos','wallet','','secondary')}${goButton('Histórico de ofertas','history','','quiet')}</div></div><aside class="m-panel"><h2>Solicitações</h2><p>${state.requests.filter(x=>x.driverId===p.id&&x.status==='pending').length} pedido(s) aguardando você</p>${goButton('Analisar solicitações','passengers','requests','secondary')}</aside></div><h2 class="m-section">Seus próximos trechos</h2>${own.length?`<div class="m-list">${own.map(r=>rideRow(r,true)).join('')}</div>`:notice('Nenhum trecho publicado. Use Publicar carona para criar sua primeira oferta.')}<h2 class="m-section">Rotinas e disponibilidade</h2>${state.routines.filter(x=>x.driverId===p.id).map(x=>`<article class="m-row"><div><h3>${esc(x.region)} ↔ UNICEPLAC</h3><p>${x.status==='active'?'Aberta a novos planos':'Novas contratações pausadas'}</p></div>${actionButton(x.status==='active'?'Pausar novos planos':'Retomar planos','routineAvailability',{routineId:x.id,active:x.status!=='active'},'quiet')}</article>`).join('')}<h2 class="m-section">Lista de interesse</h2>${state.waitlist.filter(x=>x.status==='waiting'&&get('routines',x.routineId)?.driverId===p.id).map(x=>`<div class="m-row"><div><h3>${esc(D.user(state,x.userId).name)}</h3><p class="m-help">${x.priority?'Prioridade proposta por encerramento anterior':'Interesse registrado'} · ${D.sameClass(D.user(state,x.userId),p)?'Mesma turma':'Dados acadêmicos mudaram'}</p></div></div>`).join('')||'<p class="m-muted">Nenhuma pessoa na lista. Interesse não garante nem ocupa vaga.</p>'}<details class="m-section"><summary>Alterar veículo ou reenviar documentos fictícios</summary>${driverForm(p)}</details>`:`<div class="m-grid m-section"><div><h2>Comece pelo seu veículo</h2><p class="m-muted">A aprovação de motorista e veículo é necessária antes de publicar.</p>${driverForm(p)}</div><aside class="m-panel"><h2>Documentos de exemplo</h2><p>Para apresentar este MVP, use o pacote fictício de identificação e CNH. Não envie documentos reais.</p><p class="m-help">Os dados acadêmicos são autodeclarados. A análise administrativa também é uma simulação.</p>${goButton('Conferir perfil','perfil','','quiet')}</aside></div>`}`;
    }
    function driverForm(p){return form('applyDriver',`<div class="m-two">${field('model','Modelo do veículo',p.vehicle?.model||'','','required maxlength="80"')}${field('color','Cor',p.vehicle?.color||'','text','required maxlength="40"')}</div><div class="m-two">${field('plate','Placa fictícia',p.vehicle?.plate||'','text','required maxlength="8"', 'Exemplo: UNI1A23')}${field('capacity','Vagas de passageiros',p.vehicle?.capacity||3,'number','required min="1" max="8" step="1"','Não conte o motorista.')}</div>${check('documents','Anexar identificação e CNH fictícias para análise')}<p class="m-help">Mudanças relevantes exigem nova aprovação e não podem reduzir a capacidade de reservas existentes.</p>`,'Enviar para análise fictícia');}
    function offer(edit=false){const p=me();if(p.driverStatus!=='approved')return notice('Conclua a aprovação de motorista e veículo antes de publicar.')+goButton('Cadastro de motorista','driver');const r=edit?get('rides',ref):null;if(edit&&(!r||r.driverId!==p.id))throw Error('Oferta não disponível neste perfil.');
      return `<div class="m-grid"><div>${form(edit?'editOffer':'createOffer',`${!edit?select('type','Modalidade',[['avulsa','Carona avulsa'],['mensal','Rotina mensal']],'avulsa')+field('region','Região do trajeto',p.region,'text','required maxlength="100"')+field('meeting','Ponto de encontro','','text','required maxlength="180"')+select('direction','Sentido',[['ida','Ida para a UNICEPLAC'],['volta','Volta da UNICEPLAC'],['ambos','Ida e volta (somente mensal)']],'ida')+`<div class="m-two">${field('date','Data da carona',D.nowDate(state),'date',`min="${D.nowDate(state)}"`)}${field('time','Horário de saída','18:30','time','required')}</div><div data-m-monthly-fields hidden>${field('returnTime','Horário de volta','22:10','time')}${days()}</div>`:''}<div class="m-two">${field('capacity','Vagas de passageiros',r?.capacity||p.vehicle.capacity,'number',`required min="1" max="${p.vehicle.capacity}" step="1"`)}${field('distance','Distância ilustrativa em km',r?.distance||20,'number','required min="0.1" max="2000" step="0.1"')}</div>${field('toll','Pedágio em R$',r?.toll||0,'number','min="0" step="0.01" max="2000"')}<label class="m-field"><span>Observações (opcional)</span><textarea name="notes" maxlength="600" placeholder="Detalhes úteis para o encontro">${esc(r?.notes||'')}</textarea></label>${check('automatic','Aceitar automaticamente pedidos avulsos',r?.automatic||false)}<p class="m-help">O plano mensal sempre exige aceite específico. Reservas já pagas mantêm seu preço.</p>`,edit?'Salvar oferta':'Publicar oferta',edit?{rideId:r.id}:{})}</div><aside class="m-panel"><h2>Preço por trecho</h2><strong class="m-price" data-m-quote>${cash(D.calculatePrice(r?.distance||20,{...state.params,referencePassengers:Math.min(state.params.referencePassengers,r?.capacity||p.vehicle.capacity)},r?.toll||0).cents)}</strong><p class="m-help">Cálculo ilustrativo por passageiro. O mapa não mede o percurso.</p>${summary([['Combustível',`${cash(state.params.fuel*100)}/litro`],['Consumo',`${state.params.efficiency} km/l`],['Desgaste',`${cash(state.params.wear*100)}/km`],['Comissão de teste',`${Math.round(state.params.commission*100)}%`]])}<p class="m-help">Custo = distância × (combustível ÷ consumo + desgaste) + pedágio. Dividimos com o motorista e passageiros de referência, depois incluímos a comissão.</p></aside></div>`;
    }
    function requestRow(r){return `<article class="m-panel m-section">${person(D.user(state,r.passengerId))}<p>${r.type==='mensal'?'Plano mensal':'Carona avulsa'} · ${r.lines.length} trecho(s) · ${cash(r.totalCents)}</p>${badge(r.status)}${r.type==='mensal'?`<details class="m-section"><summary>Conferir agenda solicitada</summary><div class="m-scroll">${r.lines.map(l=>`<p>${dateLabel(l.date)} · ${l.direction} ${esc(l.time)} · ${cash(l.cents)}</p>`).join('')}</div></details>`:''}${r.status==='accepted'?`<div class="m-actions">${actionButton('Encerrar pedido não pago','expireRequest',{requestId:r.id,reason:'Pedido aceito e não pago, encerrado pelo motorista'},'quiet','Nenhum pagamento foi recebido. Encerrar este pedido?')}</div>`:''}${r.status==='pending'?`<div class="m-actions">${actionButton('Aceitar pedido','replyRequest',{requestId:r.id,accept:true})}${goButton('Rejeitar pedido','report',`${r.passengerId}|${r.id}|reject`,'quiet')}${actionButton('Encerrar pedido','expireRequest',{requestId:r.id,reason:'Pedido encerrado no exemplo'},'quiet','Nenhum pagamento foi recebido. Encerrar este pedido?')}</div>`:''}</article>`;}
    function passengers(){const p=me();if(ref==='requests')return state.requests.filter(x=>x.driverId===p.id).length?state.requests.filter(x=>x.driverId===p.id).slice().reverse().map(requestRow).join(''):empty('Nenhuma solicitação','Quando alguém pedir uma vaga, você poderá analisar aqui.','driver','Ver minhas ofertas');
      const ride=get('rides',ref);if(!ride||ride.driverId!==p.id)throw Error('Trecho não disponível neste perfil.');const reservations=state.reservations.filter(x=>x.rideId===ride.id),requests=state.requests.filter(x=>x.driverId===p.id&&x.status==='pending'&&x.lines.some(l=>l.rideId===ride.id));
      return `${badge(ride.status)}<p class="m-route">${esc(ride.origin)} → ${esc(ride.destination)}</p>${summary([['Quando',`${dateLabel(ride.date)} · ${ride.time}`],['Vagas',`${D.occupied(state,ride.id)} ocupadas de ${ride.capacity}`],['Encontro',ride.meeting]])}<div class="m-actions">${ride.status==='planned'?actionButton('Iniciar trecho','startRide',{rideId:ride.id}):''}${ride.status==='planned'?goButton('Editar oferta','edit',ride.id,'quiet'):''}${['planned','active'].includes(ride.status)?goButton('Cancelar trecho','report',`|${ride.id}|driverCancel`,'quiet'):''}</div>${ride.proposedTime?notice(`Proposta: ${ride.proposedTime}. O horário ${ride.time} permanece até o consenso.`)+actionButton('Preservar horário original','keepOriginalTime',{rideId:ride.id},'quiet'):''}${ride.status==='active'?form('finishRide',check('availability','Declaro disponibilidade cumprida para mensalistas ausentes')+`<p class="m-help">Ausência mensal não é embarque. O registro é separado e contestável. Avulsa sem embarque vai à análise.</p>`,'Declarar conclusão',{rideId:ride.id}):''}<h2 class="m-section">Passageiros</h2>${reservations.length?reservations.map(r=>`<article class="m-panel m-section">${person(D.user(state,r.passengerId))}<p>${badge(r.status)} ${r.contractId?'<span class="m-badge">Mensalista</span>':''} · ${cash(r.priceCents)}</p>${r.status==='confirmed'?form('board',field('pin','PIN do passageiro','','text','required inputmode="numeric" minlength="4" maxlength="4"'),'Registrar embarque',{reservationId:r.id}):''}${r.contractId?goButton('Ver plano do mensalista','contract',r.contractId,'quiet'):''}</article>`).join(''):notice('Nenhum passageiro confirmado. Pedidos sem pagamento não ocupam vaga.')}<h2 class="m-section">Pedidos deste trecho</h2>${requests.map(requestRow).join('')||'<p class="m-muted">Nenhum pedido pendente.</p>'}${ride.status==='planned'?`<details class="m-section"><summary>Propor novo horário</summary>${form('proposeTime',field('time','Novo horário',ride.time,'time','required')+textarea('reason','Motivo da mudança'),'Notificar proposta',{rideId:ride.id})}<p class="m-help">A mudança depende do acordo. Avulso que recusar recebe crédito integral; mensal sem consenso exige preservar o horário ou cancelar o trecho.</p></details><details class="m-section"><summary>Registrar Sem aula posterior à contratação</summary>${form('noClass',textarea('reason','Motivo do registro'),'Notificar Sem aula',{rideId:ride.id})}<p class="m-help">No mensal já pago, não recalculamos o preço. A parcela é destinada integralmente ao app após confirmação ou a janela proposta sem contestação; não há comissão adicional.</p></details>`:''}`;
    }
    function wallet(){const w=D.wallet(state);const list=state.parcels.filter(x=>[x.passengerId,x.driverId].includes(me().id));return `<p class="m-muted">Valores fictícios, separados conforme a situação de cada parcela.</p><div class="m-wallet">${[['available','Disponível para saque'],['credit','Crédito para caronas'],['future','Trechos futuros'],['blocked','Em análise'],['processing','Em processamento'],['withdrawn','Saques concluídos']].map(([k,l])=>`<div><span>${l}</span><strong>${cash(w[k])}</strong></div>`).join('')}</div><div class="m-two m-section"><div>${me().driverStatus==='approved'?form('withdraw',field('amount','Valor do saque fictício em R$','','number',`min="0.01" max="${w.available/100}" step="0.01" required`),'Solicitar saque fictício'):''}</div><div>${form('refund',field('amount','Devolver crédito em R$','','number',`min="0.01" max="${w.credit/100}" step="0.01" required`),'Solicitar devolução fictícia')}</div></div>${notice('Trechos futuros e parcelas contestadas não podem ser sacados. Crédito é dinheiro já recebido, utilizado em outro pagamento; não é um segundo desconto. Saques e devoluções passam pela administração de exemplo.')}<h2 class="m-section">Movimentações</h2>${list.length?`<div class="m-list">${list.slice().reverse().map(x=>`<div class="m-row"><div><h3>${cash(x.cents)}</h3><p>${badge(x.status)}</p><p class="m-help">${esc(x.reason||'Parcela de trecho confirmado')}</p>${x.status==='released'?`<p class="m-help">Motorista ${cash(x.driverCents)} · comissão ${cash(x.commissionCents)}</p>`:''}</div>${goButton('Ver trecho',x.passengerId===me().id?'reservation':'passengers',x.passengerId===me().id?x.reservationId:get('reservations',x.reservationId).rideId,'quiet')}</div>`).join('')}</div>`:empty('Nenhuma movimentação','Pagamentos e parcelas aparecerão aqui após suas primeiras reservas.')}<h2 class="m-section">Saques e devoluções</h2>${state.withdrawals.concat(state.refunds).filter(x=>x.userId===me().id).map(x=>`<div class="m-row"><div><h3>${cash(x.cents)}</h3><p>${badge(x.status)} · ${esc(x.id)}${x.cadence?` · preferência ${x.cadence==='monthly'?'mensal':'diária'}`:''}</p></div></div>`).join('')||'<p class="m-muted">Nenhuma transferência solicitada.</p>'}`;}
    function profileView(){const p=me();if(p.role==='admin')return notice('O administrador de exemplo não possui perfil acadêmico.')+goButton('Administração','admin');const courses=window.UniCaronaSelectionData?.courses||[];
      return `<div class="m-grid"><div>${person(p)}<div class="m-section">${form('saveProfile',field('name','Nome completo',p.name,'text','required maxlength="120"')+field('course','Curso',p.course,'text','required maxlength="120" list="m-courses"')+`<datalist id="m-courses">${courses.map(c=>`<option value="${esc(typeof c==='string'?c:c.name||c.label)}"></option>`).join('')}</datalist>`+select('periodStatus','Como você está cursando?',[['numbered','Estou em um período específico'],['irregular','Faço matérias de períodos diferentes'],['undefined','Ainda não tenho período definido']],p.periodStatus||'numbered')+field('periodNumber','Número do período',p.periodNumber||'','number','min="1" max="30" step="1"', 'Obrigatório quando você está em um período específico.')+select('shift','Horário das aulas',[['','Selecione o turno'],...Object.entries(shifts)],p.shift)+select('classLabel','Turma (opcional)',[['','Não informada'],['A','Turma A'],['B','Turma B'],['C','Turma C']],p.classLabel)+`<details class="m-notice"><summary>Qual turma escolher?</summary><p>Se seu curso não divide turmas, ou possui só uma, selecione A.</p></details>`+field('region','Região onde mora',p.region,'text','required maxlength="100"')+field('phone','Telefone com DDD (opcional)',p.phone,'tel','maxlength="25" autocomplete="tel"')+field('email','E-mail',p.email||'','email','required maxlength="120"')+`<label class="m-field"><span>Foto de perfil (opcional)</span><input name="photoFile" type="file" accept="image/png,image/jpeg,image/webp"><small class="m-help">Até 2 MB. A foto fica somente nesta sessão demonstrativa.</small></label>`,'Salvar perfil')}</div></div><aside class="m-panel"><h2>Seu vínculo acadêmico</h2><p>UNICEPLAC · Gama, DF</p><p class="m-help">Dados autodeclarados. O mensal precisa da mesma combinação de curso, período numérico e turma.</p>${notice('Mudar curso, período ou turma pode encerrar vínculos mensais incompatíveis e creditar parcelas futuras. A confirmação aparece antes de salvar.')}<div class="m-actions">${goButton('Configurações','settings','','quiet')}${goButton('Cadastro de motorista','driver','','quiet')}</div></aside></div>`;
    }
    function settings(){const p=me();const blocks=state.blocks.filter(x=>x.by===p.id&&x.active);return `${form('settings',check('notices','Receber avisos da lista de interesse',p.settings.notices)+select('withdrawal','Preferência de saque fictício',[['daily','Diário'],['monthly','Mensal']],p.settings.withdrawal),'Salvar preferências')}${notice('A preferência de saque é registrada em cada pedido para análise manual. Preferências não substituem os avisos de segurança, pagamento e confirmação necessários ao fluxo. Não há notificações externas nem saques automáticos reais.')}<h2 class="m-section">Pessoas que você bloqueou</h2>${blocks.map(x=>`<div class="m-row"><div><h3>${esc(D.user(state,x.other).name)}</h3><p class="m-help">Novas combinações impedidas nos dois sentidos.</p></div>${actionButton('Desbloquear','unblock',{blockId:x.id},'quiet','Retirar o bloqueio não reativa contratos encerrados.')}</div>`).join('')||'<p class="m-muted">Você não bloqueou nenhuma pessoa.</p>'}<div class="m-actions">${goButton('Editar perfil','perfil','','secondary')}${goButton('Apresentação e cenários','demo','','quiet')}<a href="login.html" class="m-button quiet" data-m-logout>Sair da sessão</a></div>`;}
    function safety(){const cases=state.reports.filter(x=>x.by===me().id);return `<p class="m-muted">Você pode relatar antes, durante ou depois do trecho, inclusive sem embarcar ou após cancelamento.</p>${goButton('Relatar uma ocorrência','report')}<div class="m-grid m-section"><div><h2>Confira antes de embarcar</h2><p>Verifique o modelo, a cor e a placa. Se houver divergência, recuse o embarque e registre o ocorrido. Essa recusa não gera penalidade automática.</p><h2>Ajuda em situação de risco</h2><p>190: emergência policial. 180: orientação e atendimento à mulher. Use os serviços conforme a situação.</p><div class="m-actions">${actionButton('Informações sobre 190','emergency',{number:'190'},'quiet')}${actionButton('Informações sobre 180','emergency',{number:'180'},'quiet')}</div></div><aside class="m-panel"><h2>Bloqueio e análise</h2><p>Bloquear impede novos encontros nos dois sentidos. A outra pessoa não recebe a identidade de quem bloqueou.</p><p class="m-help">Incidentes graves podem interromper o vínculo imediatamente. A apuração do dinheiro fica separada, sem esperar três faltas.</p></aside></div><h2>Seus relatos e análises</h2>${cases.length?cases.map(c=>`<article class="m-row"><div><h3>${c.kind==='safety'?'Ocorrência de segurança':c.kind==='absence_review'?'Análise de ausências':'Análise financeira'}</h3>${badge(c.status)}<p>${esc(c.reason)}</p>${c.decision?`<p class="m-help">Decisão: ${esc(c.decision)}</p>`:''}</div></article>`).join(''):empty('Nenhum relato','Quando você registrar uma ocorrência, o andamento aparecerá aqui.','report','Registrar relato')}`;}
    function report(){const [otherId,target,kind]=ref.split('|');const others=state.users.filter(x=>x.id!==me().id&&x.role!=='admin');const other=others.some(x=>x.id===otherId)?otherId:others[0]?.id;
      const op={dispute:'contest',cancel:'cancelPassenger',absence:'notifyAbsence',remove:'removeMonthly',reject:'replyRequest',driverCancel:'cancelRide'}[kind]||'report';const input=kind==='remove'?{contractId:target}:kind==='reject'?{requestId:target,accept:false}:kind==='driverCancel'?{rideId:target}:{reservationId:target||''};
      return `${notice(kind==='cancel'?'O cancelamento avulso pelo passageiro irá à análise. A política financeira não está definida na documentação; não há multa ou estorno automático.':kind==='absence'?'Avisar ausência mantém a vaga e o valor do mensal. O motorista registra sua disponibilidade separadamente, sem inventar embarque.':kind==='remove'?'Parcelas futuras do vínculo serão creditadas integralmente. O passageiro entra na lista prioritária proposta, sem garantia de substituição.':kind==='driverCancel'?'As parcelas pagas deste trecho serão creditadas integralmente, sem comissão. O sentido oposto permanece.':kind==='dispute'?'A contestação bloqueia só a parcela envolvida enquanto estiver pendente. Uma parcela já encerrada não é revertida automaticamente.':'Descreva o fato. Segurança e decisão financeira serão analisadas separadamente.')}${form(op,op==='report'?select('other','Pessoa envolvida',others.map(x=>[x.id,x.name]),other)+textarea('reason','O que aconteceu?')+check('block','Impedir novas combinações com essa pessoa')+check('severe','Há risco grave ou imediato'):textarea('reason',kind==='reject'?'Motivo da rejeição':'Explique o motivo'),op==='report'?'Enviar relato':'Confirmar registro',input)}`;
    }
    function notifications(){const list=state.notifications.filter(x=>x.userId===me().id);return list.length?`<div class="m-list">${list.map(n=>`<article class="m-row"><div><h3>${esc(n.title)} ${n.read?'':'<span class="m-badge">Novo</span>'}</h3><p>${esc(n.body)}</p></div>${actionButton('Abrir aviso','openNotice',{noticeId:n.id},'secondary')}</article>`).join('')}</div>`:empty('Você está em dia','Avisos de pedidos, reservas e análises aparecerão aqui.');}
    function adminView(){if(me().role!=='admin')return notice('A administração está disponível somente no perfil demonstrativo de administrador.')+goButton('Trocar perfil de apresentação','demo');const recon=D.reconciliation(state);
      return `<p class="m-muted">Ambiente de administração fictícia. Decisões registradas no diário da demonstração.</p><div class="m-tabs">${['approvals','cases','accounts','calendar','transfers','params','audit'].map((k,i)=>`<button type="button" class="m-button quiet" data-m-admin="${k}" aria-pressed="${ref===k||(!ref&&!i)}">${['Aprovações','Ocorrências','Contas','Calendário','Transferências','Parâmetros','Conciliação'][i]}</button>`).join('')}</div>${adminSection(ref||'approvals',recon)}`;
    }
    function adminSection(section,recon){
      if(section==='approvals')return state.applications.length?state.applications.slice().reverse().map(a=>`<section class="m-panel m-section"><h2>${esc(D.user(state,a.userId).name)}</h2>${badge(a.status)}${summary([['Veículo',`${a.vehicle.model} · ${a.vehicle.color}`],['Placa',a.vehicle.plate],['Vagas',a.vehicle.capacity],['Documentos',a.documentLabel]])}${a.status==='pending'?form('reviewDriver',select('approve','Decisão',[['true','Aprovar motorista e veículo'],['false','Rejeitar e solicitar ajuste']])+textarea('reason','Justificativa'),'Registrar decisão',{applicationId:a.id}):notice(a.decision)}</section>`).join(''):empty('Nenhum cadastro em análise','Envie o cadastro fictício de um aluno para percorrer a aprovação.','demo','Trocar perfil');
      if(section==='cases')return state.reports.length?state.reports.slice().reverse().map(c=>`<section class="m-panel m-section"><h2>${esc(c.id)}</h2>${badge(c.status)}<p>${esc(c.reason)}</p><p class="m-help">Relator ${esc(D.user(state,c.by).name)} · ${c.severe?'Relato grave':'Análise ordinária'}</p>${['pending','financial_pending'].includes(c.status)?form('reviewCase',select('outcome','Decisão financeira',[['no_financial_change','Manter análise financeira pendente'],['credited','Creditar parcela ao passageiro'],['released','Liberar ao motorista com comissão'],['retained','Destinar ao app (Sem aula apurado)']])+textarea('reason','Fundamentação'),'Concluir análise',{reportId:c.id}):notice(c.decision)}</section>`).join(''):empty('Nenhuma ocorrência','Relatos e contestações aparecerão aqui.','demo','Ver apresentação');
      if(section==='accounts')return state.users.filter(x=>x.role!=='admin').map(p=>`<section class="m-panel m-section">${person(p)}<p>${badge(p.accountStatus==='active'?'active':'blocked')}</p>${form('restrict',select('suspend','Situação',[['true','Suspender preventivamente'],['false','Restaurar acesso']])+textarea('reason','Justificativa administrativa'),'Registrar análise',{userId:p.id})}</section>`).join('');
      if(section==='calendar')return `${notice('Calendário ilustrativo. Exclua datas conhecidas antes de contratar. Se o mensal já foi pago, use Sem aula por trecho, sem reduzir o valor contratado.')}${form('calendar',field('date','Data conhecida',D.nowDate(state),'date','required')+field('title','Feriado ou recesso','','text','required maxlength="120"'),'Adicionar data')}<div class="m-list m-section">${state.calendar.map(x=>`<div class="m-row"><div><h3>${dateLabel(x.date)}</h3><p>${esc(x.title)}</p></div></div>`).join('')}</div>`;
      if(section==='transfers'){const rows=state.withdrawals.map(x=>({...x,type:'withdraw'})).concat(state.refunds.map(x=>({...x,type:'refund'})));return rows.map(x=>`<section class="m-panel m-section"><h2>${x.type==='withdraw'?'Saque':'Devolução'} · ${cash(x.cents)}</h2><p>${esc(D.user(state,x.userId).name)} · ${badge(x.status)}</p>${x.cadence?`<p class="m-help">Preferência de saque: ${x.cadence==='monthly'?'mensal':'diária'}. Processamento manual na demonstração.</p>`:''}${x.status==='pending'?form('reviewTransfer',select('approve','Resultado',[['true','Aprovar transferência fictícia'],['false','Falhou: devolver saldo à carteira']])+textarea('reason','Justificativa'),'Registrar resultado',{transferId:x.id,type:x.type}):notice(x.decision)}</section>`).join('')||empty('Nenhuma transferência','Solicite saque ou devolução no perfil do aluno.','demo','Trocar perfil');}
      if(section==='params')return `${notice('Parâmetros de teste, sem medição real de distância. Mudanças afetam novas cotações; reservas contratadas mantêm preço e comissão.')}${form('params',field('fuel','Combustível (R$/litro)',state.params.fuel,'number','min="0.1" max="100" step="0.01" required')+field('efficiency','Consumo (km/l)',state.params.efficiency,'number','min="1" max="100" step="0.1" required')+field('wear','Desgaste (R$/km)',state.params.wear,'number','min="0" max="20" step="0.01" required')+field('referencePassengers','Passageiros de referência',state.params.referencePassengers,'number','min="1" max="8" step="1" required')+field('commission','Comissão (fração: 0,10 = 10%)',state.params.commission,'number','min="0" max="0.95" step="0.01" required'),'Salvar parâmetros de teste')}`;
      return `<h2 class="m-section">Conciliação do dinheiro fictício</h2>${summary(Object.entries(recon).map(([k,v])=>[{received:'Entrada recebida',future:'Futuro',blocked:'Bloqueado',driver:'Disponível do motorista',credit:'Créditos não utilizados',commission:'Comissão',retained:'Retido pelo app',withdrawn:'Saques concluídos',returned:'Devoluções concluídas',processing:'Transferências em processamento',allocated:'Total alocado',difference:'Diferença'}[k],cash(v)]))}<h2 class="m-section">Diário de eventos</h2><div class="m-list">${state.events.slice().reverse().map(e=>`<div class="m-row"><div><h3>${esc(e.label)}</h3><p class="m-help">${esc(e.id)} · ${esc(new Date(e.at).toLocaleString('pt-BR'))} · ${esc(D.user(state,e.actorId).name)}</p></div></div>`).join('')||'<p>Nenhum evento ainda.</p>'}</div>`;
    }
    function demo(){return `<p class="m-muted">Percorra o MVP pelos papéis abaixo. Todos os perfis, documentos, valores e decisões são exemplos. A sessão é apagada ao sair ou recarregar.</p><div class="m-grid"><div><h2>Perfil de apresentação</h2>${form('actor',select('userId','Usar perfil',state.users.map(x=>[x.id,x.id==='student'?'Meu perfil de aluno':`${x.name}${x.id==='admin'?' · administrador':' · motorista aprovado'}`]),me().id),'Trocar perfil')}${me().id==='student'?`<div class="m-section">${actionButton('Usar perfil de exemplo','demoProfile',{},'secondary','Carregar Ana Souza, ADS, 3º período, turma A, Lago Azul neste perfil demonstrativo? Dados existentes serão substituídos; mensais incompatíveis serão encerrados com crédito das parcelas futuras.')}</div>`:''}<h2 class="m-section">Estados para testar</h2>${form('scenario',select('network','Conexão da busca',[['normal','Normal'],['offline','Sem conexão'],['error','Erro ao carregar']],state.ui.network)+select('paymentResult','Próximo pagamento',[['approved','Aprovado'],['pending','Pendente'],['failed','Não aprovado']],state.ui.paymentResult),'Aplicar cenário')}</div><aside class="m-panel"><h2>Relógio do exemplo</h2><p>${esc(new Date(state.now).toLocaleString('pt-BR'))}</p><p class="m-help">Avance como administrador para testar a janela de confirmação, vencimento e carência. Não altera o relógio do computador.</p>${me().role==='admin'?form('tick',field('hours','Avançar horas',25,'number','required min="1" max="744"'),'Avançar relógio fictício'):goButton('Trocar para administração','demo','','quiet')}<div class="m-actions">${me().role==='admin'?goButton('Abrir administração','admin'):goButton('Ver meus pedidos','minhas')}${actionButton('Reiniciar demonstração','reset',{},'quiet','Apagar pedidos, reservas e dinheiro fictício desta sessão? O perfil inicial será mantido.')}</div></aside></div>${notice('Propostas operacionais do protótipo: pedidos sem pagamento não ocupam vaga; mensal exige aceite específico; confirmação tem janela de 24h; carência é de 72h sem embarque não pago. Política financeira de cancelamento ou falta avulsa do passageiro depende de análise. Não há autenticação, Pix, saque, GPS ou chamada real.')}`;}
    function help(){return `<div class="m-list">${[['Como confirmar uma vaga?','Busque o trajeto, confira encontro e veículo, solicite a vaga e aguarde aceite quando necessário. A reserva é confirmada após pagamento fictício.'],['Como funciona o mensal?','O curso, período numérico e turma precisam ser iguais aos do motorista. Escolha os dias e sentidos; a agenda inteira precisa ter vaga. Desconto de 10% e datas conhecidas sem aula são considerados antes da cobrança.'],['O PIN conclui a viagem?','O código registra só o embarque. A confirmação final ou a janela proposta sem contestação encerra a parcela.'],['Posso cancelar a renovação?','Sim. Você mantém os direitos do período já pago e interrompe a renovação. Mudanças acadêmicas, remoção e segurança seguem regras diferentes.'],['Onde relato um problema?','Use Segurança ou a ação de ocorrência na reserva, inclusive antes do embarque. Em risco imediato, procure o serviço de emergência apropriado.']].map(([q,a])=>`<details class="m-row"><summary>${esc(q)}</summary><p class="m-help">${esc(a)}</p></details>`).join('')}</div><div class="m-actions">${goButton('Registrar ocorrência','report')}${goButton('Ver pagamentos','wallet','','quiet')}</div>`;}
    function view(){return ({results,ride:rideDetail,monthly,request:requestView,checkout,reservation,contract,minhas:mine,driver,offer:()=>offer(),edit:()=>offer(true),passengers,wallet,perfil:profileView,settings,safety,report,notifications,admin:adminView,demo,help,history:()=>{filter='history';return mine();}}[route]||(()=>empty('Tela não encontrada','Volte ao início para continuar.','inicio','Voltar ao início')))();}
    async function confirmation(text,callback){const previous=document.activeElement;dialog.innerHTML=`<h2>Confirme a ação</h2><p>${esc(text)}</p><div class="m-actions"><button class="m-button" data-dialog-confirm>Confirmar</button><button class="m-button quiet" data-dialog-close>Voltar</button></div>`;dialog.showModal();dialog.querySelector('[data-dialog-close]').focus();dialog.querySelector('[data-dialog-confirm]').onclick=()=>{dialog.close();callback();};dialog.onclose=()=>previous?.isConnected&&previous.focus();}
    function info(title,text){const previous=document.activeElement;dialog.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="m-actions"><button class="m-button" data-dialog-close>Entendi</button></div>`;dialog.showModal();dialog.onclose=()=>previous?.isConnected&&previous.focus();}
    function perform(op,input,formElement){
      try {
        if(op==='filters'){query={...query,compatibleOnly:Boolean(input.compatibleOnly),time:'time' in input?input.time:query.time,maxPrice:input.maxPrice?Math.round(Number(input.maxPrice)*100):0,automatic:Boolean(input.automatic),onlyAvailable:Boolean(input.onlyAvailable)};return render();}
        if(op==='previewMonthly'){preview=D.monthlyPreview(state,input);app.querySelector('[data-monthly-preview]').innerHTML=previewMarkup(preview);return app.querySelector('[data-monthly-preview]').scrollIntoView({block:'start',behavior:'smooth'});}
        if(op==='share'){
          const r=get('reservations',input.reservationId);if(!r||![r.passengerId,r.driverId].includes(me().id))throw Error('Reserva não disponível neste perfil.');const ride=rideFor(r);
          const text=`UniCarona — demonstração\n${dateLabel(ride.date)} ${ride.time}\n${ride.origin} → ${ride.destination}\n${D.user(state,r.driverId).name}\n${ride.vehicle.model}, ${ride.vehicle.color}, ${ride.vehicle.plate}\nEncontro: ${ride.meeting}\nSem rastreamento de localização.`;
          const previous=document.activeElement;dialog.innerHTML=`<h2>Compartilhar detalhes</h2><p>Copie e escolha com quem compartilhar. O PIN e seus dados de contato ficam fora desse resumo.</p><label class="m-field"><span>Resumo do trecho</span><textarea readonly data-share-text>${esc(text)}</textarea></label><div class="m-actions"><button class="m-button" data-m-copy>Copiar detalhes</button><button class="m-button quiet" data-dialog-close>Fechar</button></div>`;dialog.showModal();dialog.onclose=()=>previous?.isConnected&&previous.focus();
          dialog.querySelector('[data-m-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(text);notify('Detalhes copiados. Escolha onde compartilhar.');}catch{dialog.querySelector('[data-share-text]').select();notify('Selecione o resumo e copie pelo seu dispositivo.');}};return;
        }
        if(op==='contact'){
          const r=get('reservations',input.reservationId);if(!r||![r.passengerId,r.driverId].includes(me().id))throw Error('Contato disponível somente para participantes da reserva.');
          const other=D.user(state,r.passengerId===me().id?r.driverId:r.passengerId);
          return info('Contato após confirmação',`${other.name}: ${other.phone||'telefone não informado'}. Na demonstração, não abrimos WhatsApp nem enviamos mensagens. Combine o encontro e confira o veículo antes de embarcar.`);
        }
        if(op==='emergency')return info(`Atendimento ${input.number}`,input.number==='190'?'190 é o número da emergência policial. Este protótipo não inicia chamadas; use seu telefone se precisar de ajuda imediata.':'180 oferece orientação e atendimento à mulher. Este protótipo não inicia chamadas; use seu telefone para acessar o serviço.');
        if(op==='reset'){state=D.createState(profile);filter='reservations';navigate('inicio');return notify('Demonstração reiniciada.');}
        if(op==='pay')input.outcome=state.ui.paymentResult;
        if(op==='saveProfile'&&photo)input.photo=photo;
        if(op==='openNotice'){D.act(state,'readNotice',input);const n=get('notifications',input.noticeId);return navigate(n.route==='requests'?'passengers':n.route,n.route==='requests'?'requests':n.ref);}
        const result=D.act(state,op,input);
        if(op==='requestRide'||op==='requestMonthly'||op==='renewMonthly')return navigate('request',result.id);
        if(op==='pay')return navigate('checkout',result.id);
        if(op==='actor'){filter='reservations';navigate(result.role==='admin'?'admin':'inicio');return notify(`Perfil de apresentação: ${result.name}`);}
        if(op==='demoProfile'){navigate('inicio');root.querySelector('#dashboard-origin').value=me().region;return notify('Perfil fictício carregado.');}
        if(op==='createOffer')return navigate(result.times?'driver':'passengers',result.times?'':result.id);
        if(op==='applyDriver')return navigate('driver');
        if(['report','contest','cancelPassenger'].includes(op))return navigate('safety');
        if(op==='replyRequest'||op==='expireRequest')return navigate('passengers',get('rides',ref)?ref:'requests');
        if(op==='notifyAbsence')return navigate('reservation',result.id);
        if(op==='removeMonthly')return navigate('driver');
        render();notify(op==='scenario'?'Cenário aplicado.':op==='saveProfile'?'Perfil atualizado.':op==='tick'?'Relógio demonstrativo avançado.':'Registro atualizado.');
      } catch(error){
        if(formElement){const box=formElement.querySelector('.m-error');box.textContent=error.message;const inputElement=error.field?formElement.elements.namedItem(error.field):null;if(inputElement?.focus){inputElement.setAttribute('aria-invalid','true');inputElement.focus();}else{box.tabIndex=-1;box.focus();}}
        else info('Não foi possível concluir',error.message);
      }
    }
    function click(event){
      const target=event.target.closest('[data-m-go],[data-m-action],[data-m-back],[data-m-filter],[data-m-admin],[data-dialog-close],[data-m-logout]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();
      if(target.hasAttribute('data-dialog-close'))return dialog.close();
      if(target.hasAttribute('data-m-logout')){destroy();return location.assign('login.html');}
      if(target.hasAttribute('data-m-back'))return window.history.state?.uc?window.history.back():navigate('inicio');
      if(target.dataset.mGo)return navigate(target.dataset.mGo,target.dataset.ref||'');
      if(target.dataset.mFilter){filter=target.dataset.mFilter;return render();}
      if(target.dataset.mAdmin)return navigate('admin',target.dataset.mAdmin);
      const input=JSON.parse(target.dataset.input||'{}');const callback=()=>perform(target.dataset.mAction,input);
      target.dataset.confirm?confirmation(target.dataset.confirm,callback):callback();
    }
    async function submit(event){const element=event.target;if(!element.matches('[data-m-form]'))return;event.preventDefault();event.stopImmediatePropagation();const input={...JSON.parse(element.dataset.input||'{}')};new FormData(element).forEach((v,k)=>{if(k==='weekdays')input[k]=(input[k]||[]).concat(Number(v));else if(k!=='photoFile')input[k]=v;}); for(const name of ['approve','suspend'])if(name in input)input[name]=input[name]==='true';for(const c of element.querySelectorAll('input[type=checkbox]:not([name=weekdays])'))input[c.name]=c.checked;
      element.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));const invalid=[...element.querySelectorAll('input,select,textarea')].find(e=>e.name!=='photoFile'&&!e.disabled&&(!e.validity.valid||(e.required&&!e.value.trim())));if(invalid){element.querySelector('.m-error').textContent=invalid.validationMessage||'Preencha os campos obrigatórios.';invalid.setAttribute('aria-invalid','true');return invalid.focus();}
      const op=element.dataset.mForm;if(op==='saveProfile'){const current=me(),updated={...current,...input};if(!D.sameClass(current,updated)&&state.contracts.some(c=>[c.driverId,c.passengerId].includes(current.id)&&['active','grace','cancelled_renewal'].includes(c.status)))return confirmation('A mudança acadêmica pode encerrar vínculos incompatíveis e creditar as parcelas futuras. Salvar mesmo assim?',()=>perform(op,input,element));}
      const btn=element.querySelector('button[type=submit]');const originalLabel=btn.textContent;btn.disabled=true;btn.textContent='Processando…';timer=setTimeout(()=>{btn.disabled=false;btn.textContent=originalLabel;perform(op,input,element);},180);
    }
    function inputChange(event){const e=event.target;
      if(e.name==='method'){const title=app.querySelector('[data-payment-title]');if(title)title.textContent=e.value==='card'?'Cartão de exemplo':'Pix de exemplo';}
      if(e.name==='type'){const fields=app.querySelector('[data-m-monthly-fields]');if(fields)fields.hidden=e.value!=='mensal';const date=app.querySelector('[name=date]');if(date)date.disabled=e.value==='mensal';}
      if(e.name==='periodStatus'){const n=app.querySelector('[name=periodNumber]');if(n){n.disabled=e.value!=='numbered';n.required=e.value==='numbered';}}
      if(e.name==='phone'){const d=e.value.replace(/\D/g,'').slice(0,15);if(d.length>11){e.value='+'+d;return;}e.value=d.length>2?`(${d.slice(0,2)}) ${d.slice(2,d.length===11?7:6)}${d.length>6?'-'+d.slice(d.length===11?7:6):''}`:d;}
      if(['distance','capacity','toll'].includes(e.name)&&app.querySelector('[data-m-quote]')){const f=e.closest('form');try{app.querySelector('[data-m-quote]').textContent=cash(D.calculatePrice(f.elements.distance.value,{...state.params,referencePassengers:Math.min(state.params.referencePassengers,Number(f.elements.capacity.value))},f.elements.toll.value||0).cents);}catch{app.querySelector('[data-m-quote]').textContent='Confira os valores';}}
      if(e.name==='photoFile'&&e.files[0]){const file=e.files[0];if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){e.value='';return info('Confira a foto','Escolha PNG, JPG ou WebP com até 2 MB.');}const reader=new FileReader();reader.onload=()=>{photo=reader.result;notify('Foto pronta para salvar nesta sessão.');};reader.readAsDataURL(file);}
    }
    function pop(){const url=new URL(location.href);navigate(url.searchParams.get('tela')||'inicio',url.searchParams.get('id')||'',false);}
    function search(q){query=q;navigate('results');const before=app.innerHTML;app.innerHTML=`<h1 tabindex="-1">Buscando caronas</h1><div class="m-skeleton" role="status" aria-label="Carregando resultados"></div><div class="m-skeleton"></div>`;timer=setTimeout(()=>{if(route!=='results')return;if(state.ui.network!=='normal')app.innerHTML=`<h1 tabindex="-1">${state.ui.network==='offline'?'Você está sem conexão':'Não conseguimos carregar'}</h1><p class="m-muted">Nenhuma reserva foi feita. Ajuste o cenário em Apresentação e tente novamente.</p><div class="m-actions">${goButton('Tentar novamente','buscar')}${goButton('Cenários da apresentação','demo','','quiet')}</div>`;else {app.innerHTML=before;app.querySelector('h1')?.focus({preventScroll:true});}},240);}
    function destroy(){clearTimeout(timer);clearTimeout(toastTimer);root.removeEventListener('click',click,true);root.removeEventListener('submit',submit,true);root.removeEventListener('input',inputChange);root.removeEventListener('change',inputChange);window.removeEventListener('popstate',pop);app.remove();toolbar.remove();dialog.remove();toast.remove();state=null;photo='';}
    root.addEventListener('click',click,true);root.addEventListener('submit',submit,true);root.addEventListener('input',inputChange);root.addEventListener('change',inputChange);window.addEventListener('popstate',pop);updateHome();
    if(profile.photo instanceof File&&['image/png','image/jpeg','image/webp'].includes(profile.photo.type)&&profile.photo.size<=2*1024*1024){const reader=new FileReader();reader.onload=()=>{if(state){D.user(state,'student').photo=reader.result;if(route==='perfil')render();}};reader.readAsDataURL(profile.photo);}
    const url=new URL(location.href);if(url.searchParams.get('tela'))navigate(url.searchParams.get('tela'),url.searchParams.get('id')||'',false);
    return {navigate,search,destroy,info:key=>navigate(({notifications:'notifications',monthly:'monthly',safety:'safety',settings:'settings',verification:'driver',driver:'driver',payments:'wallet'}[key]||'help'),key==='monthly'?'routine-carol':'')};
  }
  window.UniCaronaMVP=Object.freeze({attach});
})();





